// Dashboard (#dashboard): a market-style home. Greeting, auto brief, KPI tiles, brand split, movers, position
// breadth, site-section heatmap and a day-wise heatmap table. Everything is computed from data the analysis
// already holds (A, D); nothing is fetched or stored here, and no text is generated by an AI service.
(function () {
  'use strict';
  if (!window.CW_VIEWS) return;
  const { V, esc, ui } = window.CW_VIEWS;
  const { pctf, spark, chart, cssVar } = ui;
  const CW = window.CW, fmtN = CW.fmtN;
  const pc = (a, b) => b ? (a - b) / b * 100 : null;
  const sgn = v => v == null || !isFinite(v) ? '—' : (v > 0 ? '+' : '') + v.toFixed(1) + '%';
  const chip = (v, inv) => { if (v == null || !isFinite(v)) return ''; const good = inv ? v < 0 : v > 0; return `<span class="db-chip ${Math.abs(v) < .05 ? '' : good ? 'up' : 'dn'}">${sgn(v)}</span>`; };
  const hello = () => { const h = new Date().getHours(); return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening'; };
  const nameKey = 'cw:name';
  const getName = () => { try { return (localStorage.getItem(nameKey) || '').slice(0, 40); } catch (e) { return ''; } };
  const clock = () => { const n = new Date(); return { d: n.toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' }), t: n.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }).toLowerCase() }; };
  const fmtD = s => s ? new Date(s + 'T00:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : '';

  // query / page movers against the previous period (by clicks)
  function movers(rows, prevRows, key) {
    const pm = new Map((prevRows || []).map(r => [r[key], r]));
    return rows.map(r => { const p = pm.get(r[key]); return { k: r[key], clicks: r.clicks, impr: r.impr, d: r.clicks - (p ? p.clicks : 0), hasPrev: !!p }; });
  }

  function brief(A, D) {
    const C = (D.C || []).slice().sort((a, b) => a.d.localeCompare(b.d));
    const m = A.coverage && A.site ? A.site : A.totNB, pv = A.coverage && A.prevSite ? A.prevSite : A.prev && A.prev.nb;
    const out = [];
    if (C.length >= 2) {
      const l = C[C.length - 1], p = C[C.length - 2], c = pc(l.clicks, p.clicks);
      out.push(`On <b>${esc(fmtD(l.d))}</b> the site got <b>${fmtN(l.clicks)}</b> clicks${c != null ? `, ${c >= 0 ? 'up' : 'down'} <b>${Math.abs(c).toFixed(1)}%</b> on the day before` : ''}.`);
    }
    if (pv && pv.clicks) { const c = pc(m.clicks, pv.clicks); out.push(`Over the whole period clicks are <b>${c >= 0 ? 'up' : 'down'} ${Math.abs(c).toFixed(1)}%</b> against the previous period, with average position at <b>${m.pos ? m.pos.toFixed(1) : '—'}</b>.`); }
    const mv = D.prevQ && D.prevQ.length ? movers(A.Q, D.prevQ, 'q').filter(x => x.hasPrev) : [];
    const up = mv.slice().sort((a, b) => b.d - a.d)[0], dn = mv.slice().sort((a, b) => a.d - b.d)[0];
    if (up && up.d > 0) out.push(`Biggest gainer: <b>${esc(up.k)}</b> (+${fmtN(up.d)} clicks).`);
    if (dn && dn.d < 0) out.push(`Biggest loser: <b>${esc(dn.k)}</b> (${fmtN(dn.d)} clicks).`);
    const near = (A.quickWins || []).length;
    if (near) out.push(`<b>${fmtN(near)}</b> searches sit just off page one: the quickest wins to go after next.`);
    return out.length ? out.map(t => `<p>${t}</p>`).join('') : '<p>Not enough data yet for a brief.</p>';
  }

  function tiles(A, D) {
    const C = D.C || [], cov = A.coverage && A.site;
    const m = cov ? A.site : A.totNB, pv = cov ? A.prevSite : A.prev && A.prev.nb;
    const t = (l, v, d, key, inv) => `<div class="db-tile"><span class="db-l">${l}</span><b class="db-v num">${v}</b><div class="db-s">${chip(d, inv)}${C.length > 3 && key ? spark(C, key, inv) : ''}</div></div>`;
    return `<div class="db-tiles">${t('Clicks', fmtN(m.clicks), pv && pc(m.clicks, pv.clicks), 'clicks')}${t('Impressions', fmtN(m.impr), pv && pc(m.impr, pv.impr), 'impr')}
      ${t('CTR', pctf(m.ctr, 2), pv && pv.ctr ? pc(m.ctr, pv.ctr) : null, 'ctr')}${t('Avg position', m.pos ? m.pos.toFixed(1) : '—', pv && pv.pos ? pc(m.pos, pv.pos) : null, 'pos', true)}
      ${t('Pages with clicks', fmtN((A.P || []).filter(p => p.clicks > 0).length), null, null)}</div>`;
  }

  function split(A) {
    const all = A.totAll || {}, b = A.totB || {}, nb = A.totNB || {}, ps = A.posDist || [];
    const sh = x => all.clicks ? (x / all.clicks * 100).toFixed(0) + '% of clicks' : '';
    const top3 = ps[0] ? ps[0].clicks : 0, tr = A.trend && A.trend.clicks;
    const sent = tr == null ? ['Not enough history', ''] : tr > 3 ? ['Growing', 'up'] : tr < -3 ? ['Declining', 'dn'] : ['Steady', ''];
    const c = (cls, l, v, s) => `<div class="db-tint ${cls}"><span class="db-l">${l}</span><b class="db-v num">${v}</b><small>${s}</small></div>`;
    return `<div class="db-tints">${c('up', 'Non-brand clicks', fmtN(nb.clicks || 0), sh(nb.clicks || 0))}${c('', 'Brand clicks', fmtN(b.clicks || 0), sh(b.clicks || 0))}
      ${c('up', 'Clicks from top-3 positions', fmtN(top3), 'non-brand searches')}${c(sent[1], 'Momentum', sent[0], tr == null ? '' : sgn(tr) + ' clicks, recent weeks')}</div>`;
  }

  function moversCard(A, D) {
    const hasPrev = !!(D.prevQ && D.prevQ.length);
    const mv = movers(A.Q, D.prevQ, 'q');
    const sets = {
      gain: hasPrev ? mv.filter(x => x.hasPrev && x.d > 0).sort((a, b) => b.d - a.d) : [],
      lose: hasPrev ? mv.filter(x => x.hasPrev && x.d < 0).sort((a, b) => a.d - b.d) : [],
      top: mv.slice().sort((a, b) => b.clicks - a.clicks)
    };
    const body = k => sets[k].slice(0, 10).map((x, i) => `<div class="db-row"><span class="db-i">${i + 1}</span><span class="db-q" title="${esc(x.k)}">${esc(x.k)}</span><span class="db-n num">${k === 'top' ? fmtN(x.clicks) : (x.d > 0 ? '+' : '') + fmtN(x.d)}</span></div>`).join('') || `<p class="empty">${hasPrev || k === 'top' ? 'Nothing here.' : 'Load a comparison period to see movers.'}</p>`;
    return `<section class="db-card"><div class="db-h"><div class="db-tabs" role="tablist"><button type="button" class="on" data-mv="gain">Gainers</button><button type="button" data-mv="lose">Losers</button><button type="button" data-mv="top">Top</button></div><a href="#queries">View all</a></div>
      <div id="db-mv-body">${body('gain')}</div><template id="db-mv-t">${['gain', 'lose', 'top'].map(k => `<div data-k="${k}">${body(k)}</div>`).join('')}</template></section>`;
  }

  function breadth(A) {
    const ps = A.posDist || [], tot = ps.reduce((s, x) => s + x.clicks, 0) || 1, n = ps.reduce((s, x) => s + x.n, 0) || 1, p1 = ps.slice(0, 2).reduce((s, x) => s + x.n, 0);
    const col = ['#22c55e', '#84cc16', '#eab308', '#f97316', '#ef4444'];
    return `<section class="db-card"><div class="db-h"><h2>Position breadth</h2></div><div class="db-br"><div class="db-donut"><canvas id="db-donut" aria-label="Searches by position"></canvas><div class="db-dc"><b>${Math.round(p1 / n * 100)}%</b><span>on page one</span></div></div>
      <div class="db-bars">${ps.map((x, i) => `<div><span>${esc(x.label)}</span><div class="db-bar"><i style="width:${Math.max(2, x.clicks / tot * 100)}%;background:${col[i % 5]}"></i></div><em class="num">${fmtN(x.n)}</em></div>`).join('')}<small>Searches by average position · bars show share of clicks</small></div></div></section>`;
  }

  function sections(A) {
    const list = (A.sections1 || []).filter(s => s.key !== '/').sort((a, b) => b.clicks - a.clicks).slice(0, 12), mx = Math.max(1, ...list.map(s => s.clicks));
    const tone = p => p <= 5 ? 'a' : p <= 10 ? 'b' : p <= 20 ? 'c' : 'd';
    return `<section class="db-card"><div class="db-h"><h2>Site sections</h2><a href="#sections">Full view</a></div>${list.length ? `<div class="db-heat">${list.map(s => `<a class="db-hs t-${tone(s.pos)}" href="#section=${encodeURIComponent(s.key)}" style="flex:${Math.max(1, Math.round(s.clicks / mx * 10))} 1 120px"><b>${esc(s.key)}</b><span class="num">${fmtN(s.clicks)} clicks</span><small>pos ${s.pos.toFixed(1)}</small></a>`).join('')}</div><p class="db-note"><i class="t-a"></i>top 5 <i class="t-b"></i>page one <i class="t-c"></i>page two <i class="t-d"></i>deeper · size = clicks</p>` : '<p class="empty">No folders in this data.</p>'}</section>`;
  }

  V.dashboard = (A, D) => {
    const DW = window.CW_DAYWISEVIEW, list = DW && D.C && D.C.length ? DW.rows(D.C).slice(-14) : [];
    const html = `<div class="db">
      <header class="db-top"><div><h1>${hello()}${getName() ? ', ' + esc(getName()) : ''}! <button type="button" class="db-name" id="db-name" title="Set your name" aria-label="Set your name">✎</button></h1><p>Here is what is happening in search for <b>${esc(D.site)}</b>${D.source === 'demo' ? ' (sample data)' : ''}.</p></div><div class="db-clk"><span id="db-cd">${esc(clock().d)}</span><b id="db-ct">${esc(clock().t)}</b>${D.start && D.end ? `<small>Data: ${esc(fmtD(D.start))} – ${esc(fmtD(D.end))}</small>` : ''}</div></header>
      <div class="db-grid1"><section class="db-card db-brief"><div class="db-h"><h2><i class="db-dot"></i> Site Brief</h2><small>Built from your data · not AI-generated</small></div>${brief(A, D)}</section>${tiles(A, D)}</div>
      ${split(A)}
      <div class="db-grid2">${moversCard(A, D)}${breadth(A)}</div>
      ${sections(A)}
      ${window.CW_TREEMAP ? `<section class="db-card"><div class="db-h"><h2>Pages map <small>· size = clicks, colour = change</small></h2><a href="#treemap">Open full map</a></div>${window.CW_TREEMAP.html(A, D, { h: 260, max: 40, tab: 'all' })}</section>` : ''}
      ${window.CW_WATCH ? window.CW_WATCH.card(A, D) : ''}
      ${DW && D.C && D.C.length ? DW.chartHtml(D, null) : ''}
      ${list.length ? `<section class="db-card"><div class="db-h"><h2>Day-wise heatmap <small>· click a day to see what happened</small></h2><a href="#stats?tab=daywise">Open full table</a></div>${DW.tableHtml(list)}</section>` : ''}
    </div>`;
    return { html, mount: () => {
      const v = document.getElementById('view'), body = document.getElementById('db-mv-body'), tpl = document.getElementById('db-mv-t');
      v.querySelectorAll('[data-mv]').forEach(b => b.addEventListener('click', () => {
        v.querySelectorAll('[data-mv]').forEach(x => x.classList.toggle('on', x === b));
        const el = tpl.content.querySelector(`[data-k="${b.dataset.mv}"]`); body.innerHTML = el ? el.innerHTML : '';
      }));
      const nb = document.getElementById('db-name');
      if (nb) nb.addEventListener('click', () => { const n = window.prompt('Your name for the greeting (leave empty to remove)', getName()); if (n === null) return; try { localStorage.setItem(nameKey, n.trim().slice(0, 40)); } catch (e) { } window.dispatchEvent(new HashChangeEvent('hashchange')); });
      const tick = setInterval(() => { const a = document.getElementById('db-cd'), b = document.getElementById('db-ct'); if (!a || !b) return clearInterval(tick); const c = clock(); a.textContent = c.d; b.textContent = c.t; }, 20000);
      if (window.CW_WATCH) window.CW_WATCH.bindStars(v, () => window.dispatchEvent(new HashChangeEvent('hashchange')));
      if (DW) { const go = day => { location.hash = '#stats?tab=daywise&day=' + day; }; DW.bindRows(v, go); DW.chartMount(D, null, go); }
      const ps = A.posDist || [];
      if (document.getElementById('db-donut') && ps.length) chart('db-donut', { type: 'doughnut', data: { labels: ps.map(x => x.label), datasets: [{ data: ps.map(x => x.n), backgroundColor: ['#22c55e', '#84cc16', '#eab308', '#f97316', '#ef4444'], borderColor: cssVar('--surface'), borderWidth: 2 }] }, options: { maintainAspectRatio: false, cutout: '72%', plugins: { legend: { display: false } } } });
    } };
  };
})();
